,STRUCT('1702081909' AS cust,'StrongTech' AS grupo)])), base AS (SELECT FORMAT_DATE('%Y-%m',ORD_CLOSED_DT) mes, CASE WHEN ITE_ITEM_FULL_UNIT_PRICE<200 THEN '1_<200' WHEN ITE_ITEM_FULL_UNIT_PRICE<500 THEN '2_200-500' WHEN ITE_ITEM_FULL_UNIT_PRICE<1500 THEN '3_500-1500' WHEN ITE_ITEM_FULL_UNIT_PRICE<3000 THEN '4_1500-3000' ELSE '5_>3000' END AS faixa, DOM_DOMAIN_AGG2 AS d2, CAST(CUS_CUST_ID_SEL AS STRING) AS cust, SELLER_NAME AS nick, F_NMV_LC AS nmv, F_NSI AS nsi, ITE_ITEM_ID AS iid, COALESCE(NULLIF(ITE_ITEM_BRAND,''),'(sem marca)') AS brand FROM `meli-bi-data.WHOWNER.DM_EFICIENCIA_MLB` WHERE VERTICAL='HOME ELECTRONICS' AND DOM_DOMAIN_AGG1='LARGE APPLIANCES' AND SEGMENTO_DETAIL='CA' AND ORD_CLOSED_DT BETWEEN '2025-01-01' AND '2026-07-31' AND ITE_ITEM_FULL_UNIT_PRICE>0), g AS (SELECT b.mes,b.faixa,b.d2,b.iid,b.brand,b.nmv,b.nsi, COALESCE(dep.grupo,b.nick) AS grupo FROM base b LEFT JOIN dep ON b.cust=dep.cust), rk AS (SELECT grupo, SUM(nmv) sn, SUM(nsi) ss FROM g GROUP BY 1), named AS (SELECT grupo FROM (SELECT grupo, ROW_NUMBER() OVER(ORDER BY sn DESC) rn, ROW_NUMBER() OVER(ORDER BY ss DESC) rs FROM rk) WHERE rn<=50 OR rs<=50) SELECT g.mes, g.faixa, g.d2, IF(n.grupo IS NULL,'Outros',g.grupo) AS grupo, ROUND(SUM(g.nmv)/1e6,4) AS nmv_mi, ROUND(SUM(g.nsi),4) AS nsi, COUNT(DISTINCT g.iid) AS itens, COUNT(DISTINCT g.brand) AS marcas FROM g LEFT JOIN named n ON g.grupo=n.grupo GROUP BY 1,2,3,4